package com.example.backend.service.notification;
import com.example.backend.dto.notification.NotificationResponse; import com.example.backend.entity.*; import com.example.backend.repository.NotificationRepository; import org.springframework.messaging.simp.SimpMessagingTemplate; import org.springframework.stereotype.Service;
@Service public class NotificationService { private final NotificationRepository repository; private final SimpMessagingTemplate broker; public NotificationService(NotificationRepository r,SimpMessagingTemplate b){repository=r;broker=b;} public void notify(User recipient,User actor,NotificationType type,Long resourceId,String message){if(recipient.getId().equals(actor.getId()))return; NotificationResponse response=NotificationResponse.from(repository.save(new Notification(recipient,actor,type,resourceId,message)));broker.convertAndSendToUser(recipient.getEmail(),"/queue/notifications",response);}}
